    'options.aboutHeading': `O tym rozszerzeniu`,
    'options.aboutText': `Jeden rycerz, jedna krucjata: dopracowane narzędzia open source, których nie było w takiej postaci, jakiej chciałem, budowane, aż niczego nie zabraknie. Wszystko za darmo, bez kont, bez telemetrii, bez reklam i bez płatnych wersji. Nigdzie żadnej gwiazdki. Nic czytelnego nigdy nie opuszcza twoich własnych murów. Kute wieczorami i w weekendy, z sercem i uporem.`,
