    'options.seconds': `секунд`,
    'options.pinHeading': `Почти готово`,
    'options.pinBody': `KnightLoader установлен. Браузер прячет новые расширения за значком пазла на панели инструментов. Нажмите на него, а затем на булавку рядом с KnightLoader, чтобы он остался на виду.`,
    'options.pinDismiss': `Понятно`,
    'options.aboutHeading': `Об этом расширении`,
    'options.aboutText': `Один рыцарь, один поход: аккуратные открытые инструменты, которых не было в том виде, в каком я хотел, и они строятся, пока ничего не будет не хватать. Всё бесплатно, без аккаунтов, без телеметрии, без рекламы и без платных тарифов. Нигде ни одной звёздочки. Ничего читаемого никогда не покидает твоих стен. Выковано вечерами и по выходным, с сердцем и упрямством.`,
    'options.aboutCoffeeButton': `Угостить кофе`,
    'options.coffeeIntro': `Оплата проходит через Buy Me a Coffee, картой или электронным кошельком. Аккаунт не нужен.`,
    'options.aboutPaypal': `PayPal`,
    'options.aboutCrypto': `Крипто`,
    'options.cryptoTitle': `Поддержать криптовалютой`,
    'options.cryptoIntro': `Выбери монету и сеть, затем отсканируй код или скопируй адрес.`,
    'options.cryptoNetworks': `Сети`,
    'options.cryptoNoTag': `Ни тег назначения, ни мемо не нужны.`,
    'options.aboutCoffee': `Если KnightLoader заслужил место на твоём сервере или компьютере, брось монету своему рыцарю: она помогает покрыть расходы и держит проект живым. И сердце этого рыцаря бьётся немного быстрее. Ниже три пути, выбери тот, что тебе подходит.`,
    'options.aboutReport': `Проблемы, пожелания или предложения? Заведите задачу на GitHub или напишите письмо.`,
    'options.aboutVersion': `Версия`,
    'options.aboutGithub': `GitHub`,
