    'options.seconds': `секунд`,
    'options.pinHeading': `Майже готово`,
    'options.pinBody': `KnightLoader встановлено. Браузер ховає нові розширення за значком пазла на панелі інструментів. Натисніть його, а потім шпильку поруч із KnightLoader, щоб він залишався на видноті.`,
    'options.pinDismiss': `Зрозуміло`,
    'options.aboutHeading': `Про це розширення`,
    'options.aboutText': `Один лицар, один похід: охайні відкриті інструменти, яких не було в тому вигляді, який я хотів, і вони будуються, доки нічого не бракуватиме. Усе безкоштовно, без облікових записів, без телеметрії, без реклами і без платних тарифів. Ніде жодної зірочки. Нічого читабельного ніколи не полишає твоїх стін. Викуто вечорами й на вихідних, із серцем і впертістю.`,
    'options.aboutCoffeeButton': `Пригостити кавою`,
    'options.coffeeIntro': `Оплата йде через Buy Me a Coffee, карткою або електронним гаманцем. Обліковий запис не потрібен.`,
    'options.aboutPaypal': `PayPal`,
    'options.aboutCrypto': `Крипто`,
    'options.cryptoTitle': `Підтримати криптовалютою`,
    'options.cryptoIntro': `Обери монету та мережу, потім скануй код або скопіюй адресу.`,
    'options.cryptoNetworks': `Мережі`,
    'options.cryptoNoTag': `Ані тег призначення, ані мемо не потрібні.`,
    'options.aboutCoffee': `Якщо KnightLoader заслужив місце на твоєму сервері чи комп'ютері, кинь монету своєму лицарю: вона допомагає покрити витрати й тримає проєкт живим. І серце цього лицаря б'ється трохи швидше. Нижче три шляхи, обери той, що тобі до вподоби.`,
    'options.aboutReport': `Проблеми, побажання чи пропозиції? Створіть задачу на GitHub або напишіть листа.`,
