    'options.seconds': `sekund`,
    'options.pinHeading': `Skoro hotovo`,
    'options.pinBody': `KnightLoader je nainstalovaný. Prohlížeč schovává nová rozšíření za ikonu puzzle na liště. Klikněte na ni a pak na špendlík vedle KnightLoaderu, aby zůstal na očích.`,
    'options.pinDismiss': `Rozumím`,
    'options.aboutHeading': `O tomto rozšíření`,
    'options.aboutText': `Jeden rytíř, jedna výprava: pěkné open source nástroje, které v podobě, jakou jsem chtěl, neexistovaly, stavěné, dokud nic nechybí. Všechno zdarma, bez účtů, bez telemetrie, bez reklam a bez placených verzí. Nikde žádná hvězdička. Nic čitelného nikdy neopustí tvoje vlastní zdi. Kováno po večerech a o víkendech, se srdcem a tvrdohlavostí.`,
    'options.aboutCoffeeButton': `Kup mi kávu`,
    'options.coffeeIntro': `Platba probíhá přes Buy Me a Coffee, kartou nebo peněženkou. Účet k tomu nepotřebuješ.`,
