    'options.cryptoNoTag': `Destination tag ani memo nejsou potřeba.`,
    'options.aboutCoffee': `Jestli si KnightLoader zasloužil místo na tvém serveru nebo počítači, hoď groš svému rytíři: pomůže pokrýt náklady a udrží projekt naživu. A srdce tohohle rytíře díky tomu bije o něco rychleji. Níže jsou tři cesty, vyber si tu, která ti vyhovuje.`,
    'options.aboutReport': `Problémy, přání nebo návrhy? Založ issue na GitHubu, nebo pošli e-mail.`,
