    'options.pinBody': `KnightLoader on asennettu. Selain piilottaa uudet laajennukset työkalurivin palapelikuvakkeen taakse. Napsauta sitä ja sitten KnightLoaderin vieressä olevaa nuppineulaa, niin se pysyy näkyvissä.`,
    'options.pinDismiss': `Selvä`,
    'options.aboutHeading': `Tietoja tästä laajennuksesta`,
    'options.aboutText': `Yksi ritari, yksi ristiretki: siistejä avoimen lähdekoodin työkaluja, joita ei ollut siinä muodossa kuin halusin, rakennettuna kunnes mitään ei puutu. Kaikki ilmaista, ilman tilejä, ilman telemetriaa, ilman mainoksia ja ilman maksullisia tasoja. Ei tähteä missään. Mikään luettava ei koskaan poistu omien muuriesi sisältä. Taottu iltaisin ja viikonloppuisin, sydämellä ja itsepäisyydellä.`,
