    'options.pinHeading': `Почти готово`,
    'options.pinBody': `KnightLoader е инсталиран. Браузърът крие новите разширения зад иконата с пъзел в лентата с инструменти. Щракнете върху нея, а после върху карфицата до KnightLoader, за да остане видим.`,
    'options.pinDismiss': `Разбрах`,
    'options.aboutHeading': `За това разширение`,
    'options.aboutText': `Един рицар, един поход: спретнати инструменти с отворен код, които ги нямаше във вида, който исках, и се градят, докато нищо не липсва. Всичко е безплатно, без акаунти, без телеметрия, без реклами и без платени нива. Никъде нито една звездичка. Нищо четимо никога не напуска твоите стени. Кове се вечер и през почивните дни, със сърце и инат.`,
    'options.aboutCoffeeButton': `Почерпи ме с кафе`,
    'options.coffeeIntro': `Плащането минава през Buy Me a Coffee, с карта или дигитален портфейл. Не ти трябва акаунт.`,
