    'options.aboutCoffee': `Ако KnightLoader си е заслужил място на твоя сървър или компютър, хвърли монета на своя рицар: тя помага да се покрият разходите и държи проекта жив. И кара сърцето на този рицар да бие малко по-бързо. По-долу има три пътя, избери този, който ти допада.`,
    'options.aboutReport': `Проблеми, желания или предложения? Отвори задача в GitHub или прати имейл.`,
