    'options.cnlSub': `Οι ιστότοποι με κουμπί Click'n'Load παραδίδουν τους συνδέσμους τους σε έναν διαχειριστή λήψεων αυτού του υπολογιστή. Η επέκταση τους αναχαιτίζει, ώστε να φτάνουν σε ένα στιγμιότυπο όπου κι αν τρέχει.`,
