    'options.seconds': `δευτερόλεπτα`,
    'options.pinHeading': `Σχεδόν έτοιμο`,
    'options.pinBody': `Το KnightLoader εγκαταστάθηκε. Ο περιηγητής κρύβει τις νέες επεκτάσεις πίσω από το εικονίδιο του παζλ στη γραμμή εργαλείων. Κάντε κλικ σε αυτό και μετά στην πινέζα δίπλα στο KnightLoader για να μένει ορατό.`,
    'options.pinDismiss': `Κατάλαβα`,
    'options.aboutHeading': `Σχετικά με αυτή την επέκταση`,
    'options.aboutText': `Ένας ιππότης, μία σταυροφορία: προσεγμένα εργαλεία ανοιχτού κώδικα που δεν υπήρχαν στη μορφή που ήθελα, φτιαγμένα μέχρι να μη λείπει τίποτα. Όλα δωρεάν, χωρίς λογαριασμούς, χωρίς τηλεμετρία, χωρίς διαφημίσεις και χωρίς επί πληρωμή επίπεδα. Πουθενά αστερίσκος. Τίποτα αναγνώσιμο δεν φεύγει ποτέ από τα δικά σου τείχη. Σφυρηλατημένα τα βράδια και τα σαββατοκύριακα, με καρδιά και πείσμα.`,
    'options.aboutCoffeeButton': `Κέρασέ με έναν καφέ`,
    'options.coffeeIntro': `Η πληρωμή γίνεται μέσω Buy Me a Coffee, με κάρτα ή ψηφιακό πορτοφόλι. Δεν χρειάζεται λογαριασμός.`,
    'options.aboutPaypal': `PayPal`,
    'options.aboutCrypto': `Κρύπτο`,
    'options.cryptoTitle': `Δωρεά με κρύπτο`,
    'options.cryptoIntro': `Διάλεξε νόμισμα και δίκτυο, μετά σάρωσε τον κωδικό ή αντίγραψε τη διεύθυνση.`,
    'options.cryptoNetworks': `Δίκτυα`,
    'options.cryptoNoTag': `Δεν χρειάζεται destination tag ούτε memo.`,
    'options.aboutCoffee': `Αν το KnightLoader κέρδισε τη θέση του στον διακομιστή ή στον υπολογιστή σου, ρίξε ένα νόμισμα στον ιππότη σου: βοηθά να καλυφθούν τα έξοδα και κρατά το έργο ζωντανό. Και κάνει την καρδιά αυτού του ιππότη να χτυπά λίγο πιο γρήγορα. Πιο κάτω υπάρχουν τρεις δρόμοι, διάλεξε αυτόν που σου ταιριάζει.`,
    'options.aboutReport': `Προβλήματα, επιθυμίες ή προτάσεις; Άνοιξε ένα ζήτημα στο GitHub ή στείλε ένα email.`,
