    'options.followInstanceHint': `Οι γωνίες, τα χρώματα και η λειτουργία ουράνιου τόξου έρχονται από την προεπιλεγμένη σας εγκατάσταση. Το θέμα μένει τοπικό: ανοιχτό ή σκούρο αφορά το δωμάτιο όπου κάθεστε, όχι τον διακομιστή.`,
    'options.problemsHeading': `Προβλήματα;`,
