    'options.pinBody': `KnightLoader on paigaldatud. Brauser hoiab uusi laiendusi tööriistariba pusletüki ikooni taga. Klõpsa sellel ja seejärel KnightLoaderi kõrval oleval nööpnõelal, et see jääks nähtavale.`,
    'options.pinDismiss': `Selge`,
    'options.aboutHeading': `Sellest brauserilaiendist`,
    'options.aboutText': `Üks rüütel, üks ristisõda: korralikud avatud lähtekoodiga tööriistad, mida sellisel kujul, nagu tahtsin, ei olnud, ehitatud seni, kuni midagi puudu ei ole. Kõik tasuta, ilma kontodeta, ilma telemeetriata, ilma reklaamideta ja ilma tasuliste tasemeteta. Mitte kusagil tärnikest. Miski loetav ei lahku kunagi sinu enda müüride vahelt. Sepistatud õhtuti ja nädalavahetustel, südame ja kangekaelsusega.`,
    'options.aboutCoffeeButton': `Osta mulle kohv`,
