    'options.pinBody': `KnightLoader نصب شد. مرورگر افزونه‌های جدید را پشت نماد قطعهٔ پازل در نوار ابزار نگه می‌دارد. روی آن و سپس روی سنجاق کنار KnightLoader کلیک کنید تا در دید بماند.`,
    'options.pinDismiss': `متوجه شدم`,
    'options.aboutHeading': `درباره این افزونه`,
    'options.aboutText': `یک شوالیه، یک لشکرکشی: ابزارهای متن‌باز خوش‌ساخت که در شکلی که می‌خواستم وجود نداشتند و ساخته می‌شوند تا چیزی کم نماند. همه‌چیز رایگان، بدون حساب کاربری، بدون تله‌متری، بدون تبلیغات و بدون نسخهٔ پولی. هیچ ستاره‌ای در هیچ‌کجا. هیچ چیز خواندنی هرگز از دیوارهای خودت بیرون نمی‌رود. در شب‌ها و آخر هفته‌ها ساخته شده، با دل و یک‌دندگی.`,
