    'options.aboutHeading': `Sobre esta extensión`,
    'options.aboutText': `Un só cabaleiro, unha cruzada: ferramentas de código aberto ben feitas que non existían na forma que eu quería, construídas ata que non falte nada. Todo de balde, sen contas, sen telemetría, sen anuncios e sen plans de pago. Ningún asterisco en ningures. Nada lexible sae nunca das túas propias murallas. Forxado polas noites e as fins de semana, con corazón e teimosía.`,
