    'options.cnlSub': `אתרים עם כפתור Click'n'Load מוסרים את הקישורים שלהם למנהל הורדות במחשב הזה. ההרחבה תופסת אותם, כדי שיגיעו למופע שלכם היכן שהוא רץ.`,
