    'options.pinHeading': `כמעט סיימנו`,
    'options.pinBody': `KnightLoader הותקן. הדפדפן מסתיר תוספות חדשות מאחורי סמל חלק הפאזל שבסרגל הכלים. לחצו עליו ואז על נעץ שליד KnightLoader כדי שיישאר גלוי.`,
    'options.pinDismiss': `הבנתי`,
    'options.aboutHeading': `על התוסף הזה`,
    'options.aboutText': `אביר אחד, מסע צלב אחד: כלים נאים בקוד פתוח שלא היו קיימים בצורה שרציתי, נבנים עד שלא חסר דבר. הכול בחינם, בלי חשבונות, בלי טלמטריה, בלי פרסומות ובלי מסלולים בתשלום. שום כוכבית בשום מקום. שום דבר קריא לא עוזב אף פעם את החומות שלך. מחושל בערבים ובסופי שבוע, עם לב ועקשנות.`,
    'options.aboutCoffeeButton': `קנו לי קפה`,
    'options.coffeeIntro': `התשלום עובר דרך Buy Me a Coffee, בכרטיס או בארנק דיגיטלי. לא צריך חשבון.`,
    'options.aboutPaypal': `PayPal`,
