    'options.cryptoTitle': `תרומה בקריפטו`,
    'options.cryptoIntro': `בחר מטבע ורשת, ואז סרוק את הקוד או העתק את הכתובת.`,
    'options.cryptoNetworks': `רשתות`,
    'options.cryptoNoTag': `אין צורך ב-destination tag ולא ב-memo.`,
    'options.aboutCoffee': `אם KnightLoader הרוויח את מקומו בשרת או במחשב שלך, השלך מטבע לאביר שלך: זה עוזר לכסות את העלויות ומשאיר את הפרויקט בחיים. וזה גם גורם ללב של האביר הזה לפעום קצת יותר מהר. למטה יש שלוש דרכים, בחר את זו שמתאימה לך.`,
    'options.aboutReport': `בעיות, בקשות או הצעות? פתחו נושא ב-GitHub או שלחו מייל.`,
