    'options.aboutHeading': `इस ब्राउज़र एक्सटेंशन के बारे में`,
    'options.aboutText': `एक नाइट, एक अभियान: सुंदर ओपन-सोर्स औज़ार जो उस रूप में मौजूद नहीं थे जैसा मैं चाहता था, तब तक बनाए जाते हैं जब तक कुछ बाकी न रहे. सब कुछ मुफ़्त, बिना खाते, बिना टेलीमेट्री, बिना विज्ञापन और बिना किसी भुगतान वाले स्तर के. कहीं कोई तारांकन नहीं. पढ़ने लायक कुछ भी कभी तुम्हारी दीवारों से बाहर नहीं जाता. शामों और सप्ताहांतों में गढ़ा गया, दिल और ज़िद के साथ.`,
