    'options.pinHeading': `Næstum búið`,
    'options.pinBody': `KnightLoader er uppsett. Vafrinn geymir nýjar viðbætur bak við púslbútstáknið á tækjastikunni. Smelltu á það og svo á títuprjóninn við hliðina á KnightLoader svo það sjáist áfram.`,
    'options.pinDismiss': `Skilið`,
    'options.aboutHeading': `Um þessa vafraviðbót`,
    'options.aboutText': `Einn riddari, ein krossferð: falleg opin verkfæri sem voru ekki til í þeirri mynd sem ég vildi, smíðuð þar til ekkert vantar. Allt ókeypis, án aðganga, án fjarmælinga, án auglýsinga og án greiddra þrepa. Engin stjarna neins staðar. Ekkert læsilegt fer nokkurn tíma út fyrir þína eigin múra. Smíðað á kvöldin og um helgar, með hjarta og þrjósku.`,
    'options.aboutCoffeeButton': `Bjóddu mér kaffi`,
    'options.coffeeIntro': `Greiðslan fer í gegnum Buy Me a Coffee, með korti eða rafrænu veski. Þú þarft engan aðgang.`,
    'options.aboutPaypal': `PayPal`,
    'options.aboutCrypto': `Rafmynt`,
