    'options.cryptoNoTag': `Hvorki destination tag né memo er nauðsynlegt.`,
    'options.aboutCoffee': `Ef KnightLoader hefur unnið sér sess á þjóninum þínum eða tölvunni, kastaðu þá mynt til riddarans þíns: það hjálpar að standa straum af kostnaðinum og heldur verkefninu lifandi. Og það lætur hjarta þessa riddara slá aðeins hraðar. Hér fyrir neðan eru þrjár leiðir, taktu þá sem hentar þér.`,
    'options.aboutReport': `Vandamál, óskir eða ábendingar? Opnaðu mál á GitHub, eða sendu tölvupóst.`,
