    'options.pinHeading': `Beveik baigta`,
    'options.pinBody': `KnightLoader įdiegtas. Naršyklė naujus plėtinius laiko už dėlionės detalės piktogramos įrankių juostoje. Spustelėkite ją, tada smeigtuką šalia KnightLoader, kad jis liktų matomas.`,
