    'options.aboutHeading': `Apie šį naršyklės priedą`,
    'options.aboutText': `Vienas riteris, vienas žygis: tvarkingi atvirojo kodo įrankiai, kurių tokios formos, kokios norėjau, nebuvo, statomi tol, kol nieko netrūks. Viskas nemokama, be paskyrų, be telemetrijos, be reklamų ir be mokamų lygių. Niekur jokios žvaigždutės. Niekas skaitomo niekada neišeina už tavo paties sienų. Kalta vakarais ir savaitgaliais, su širdimi ir užsispyrimu.`,
