    'options.aboutHeading': `Perihal sambungan pelayar ini`,
    'options.aboutText': `Satu kesateria, satu ekspedisi: alat sumber terbuka yang kemas, yang tidak wujud dalam bentuk yang saya mahukan, dibina sehingga tiada apa yang kurang. Semuanya percuma, tanpa akaun, tanpa telemetri, tanpa iklan dan tanpa peringkat berbayar. Tiada tanda bintang di mana-mana. Tiada apa yang boleh dibaca pernah meninggalkan tembokmu sendiri. Ditempa pada waktu malam dan hujung minggu, dengan hati dan sifat degil.`,
