    'options.pinBody': `KnightLoader je nainštalovaný. Prehliadač skrýva nové rozšírenia za ikonu puzzle na paneli s nástrojmi. Kliknite na ňu a potom na špendlík vedľa KnightLoadera, aby zostal na očiach.`,
    'options.pinDismiss': `Rozumiem`,
    'options.aboutHeading': `O tomto rozšírení`,
    'options.aboutText': `Jeden rytier, jedna výprava: pekné open source nástroje, ktoré v podobe, akú som chcel, neexistovali, stavané, kým nič nechýba. Všetko zadarmo, bez účtov, bez telemetrie, bez reklám a bez platených verzií. Nikde žiadna hviezdička. Nič čitateľné nikdy neopustí tvoje vlastné múry. Kované po večeroch a cez víkendy, so srdcom a tvrdohlavosťou.`,
