    'options.pinDismiss': `Разумем`,
    'options.aboutHeading': `О овом додатку`,
    'options.aboutText': `Један витез, један поход: уредни алати отвореног кода којих у облику какав сам желео није било, грађени док ништа не недостаје. Све бесплатно, без налога, без телеметрије, без реклама и без плаћених нивоа. Нигде ниједне звездице. Ништа читљиво никада не напушта твоје зидове. Ковано увече и викендом, са срцем и тврдоглавошћу.`,
