let _lang = 'en';

/** baseLang strips a region subtag ("de-DE" to "de") so any browser locale matches. */
function baseLang(tag) {
  return (tag || '').toLowerCase().split(/[-_]/)[0];
}

/** resolveAuto returns the browser's UI language if the extension carries it,
 *  with navigator.language as the fallback, else English. */
function resolveAuto() {
  const candidates = [];
  try {
    if (typeof chrome !== 'undefined' && chrome.i18n?.getUILanguage) {
      candidates.push(chrome.i18n.getUILanguage());
    }
  } catch {
    /* ignore */
  }
  if (typeof navigator !== 'undefined' && navigator.language) candidates.push(navigator.language);
  for (const c of candidates) {
    const b = baseLang(c);
    if (LANGUAGES.some((l) => l.code === b)) return b;
  }
  return 'en';
}

/**
 * applyDocumentLanguage sets `lang` on <html>, which picks fonts, hyphenation
 * and quote marks, and `dir="rtl"` for the catalogues marked rtl, so the page
 * layout mirrors as well as the text. The service worker has no document.
 */
function applyDocumentLanguage(code) {
  if (typeof document === 'undefined' || !document.documentElement) return;
  const def = LANGUAGES.find((l) => l.code === code);
  document.documentElement.setAttribute('lang', code);
  document.documentElement.setAttribute('dir', def?.rtl ? 'rtl' : 'ltr');
}

/**
 * loadLanguage resolves the active language (the stored choice, otherwise the
 * browser's) and caches it for the synchronous t(). Every page and the service
 * worker call it before writing any text, and the options page calls it again
 * after a language change. It also sets <html lang> and dir.
 */
async function loadLanguage() {
  const stored = await chrome.storage.local.get('language');
  _lang =
    typeof stored.language === 'string' && stored.language && LANGUAGES.some((l) => l.code === stored.language)
      ? stored.language
      : resolveAuto();
  applyDocumentLanguage(_lang);
  return _lang;
}

/** setLanguage persists an explicit override, or clears it back to "match the browser" when code is falsy. */
async function setLanguage(code) {
  if (code) await chrome.storage.local.set({ language: code });
  else await chrome.storage.local.remove('language');
}

// The value goes in through a function, since a replacement string would read
// "$&" in a file name as a pattern.
function formatMsg(str, vars) {
  if (!vars) return str;
  let s = str;
  for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, () => String(v));
  return s;
}

/** currentLanguage is the language loadLanguage() last resolved to. */
function currentLanguage() {
  return _lang;
}

/** t looks up `key` in the language loadLanguage() last resolved, falling back to English, then to the key itself. */
function t(key, vars) {
  const dict = MESSAGES[_lang] || MESSAGES.en;
  const str = dict[key] ?? MESSAGES.en[key] ?? key;
  return formatMsg(str, vars);
}
